{
  "name": "Newport XPS多轴运动控制器",
  "name_en": "Newport XPS Motion Controller",
  "manufacturer": "Newport",
  "description": "Newport XPS是一类用于驱动和管理多轴电动位移台、直线台或旋转台的高精度运动控制器。它支持轴组初始化、回零、使能、位置运动、速度设置以及PVT轨迹扫描，常用于光学对准、精密定位、自动扫描和实验平台运动控制。",
  "description_en": "The Newport XPS is a precision multi-axis motion controller used to drive and manage motorized translation and rotation stages. It supports group initialization, homing, enabling, point-to-point motion, velocity setup, and PVT trajectory scanning, and is commonly used for optical alignment, precision positioning, automated scanning, and laboratory motion control.",
  "tag_hints": [
    "multi-axis motion control",
    "motorized stages",
    "precision positioning",
    "PVT trajectory scanning",
    "optical alignment",
    "stage homing",
    "trajectory execution"
  ],
  "actions": [
    {
      "action_name": "auto-abort_group",
      "description": "中止指定轴组的当前运动。",
      "description_en": "Abort the current motion of the selected motion group."
    },
    {
      "action_name": "auto-arm_trajectory",
      "description": "将指定轨迹置于待运行状态，并可先移动到轨迹起点。",
      "description_en": "Arm a selected trajectory for execution, optionally moving to its start position first."
    },
    {
      "action_name": "auto-check_error",
      "description": "检查控制器返回的错误状态。",
      "description_en": "Check the error status returned by the controller."
    },
    {
      "action_name": "auto-clean_folders",
      "description": "清理控制器内部存储中的相关文件夹内容。",
      "description_en": "Clean relevant folders in the controller's internal storage."
    },
    {
      "action_name": "auto-connect",
      "description": "连接到运动控制器。",
      "description_en": "Connect to the motion controller."
    },
    {
      "action_name": "auto-define_array_trajectory",
      "description": "为轴组定义按位置数组执行的PVT轨迹。",
      "description_en": "Define a PVT trajectory for a motion group from arrays of target positions."
    },
    {
      "action_name": "auto-define_line_trajectories",
      "description": "为指定轴定义线性往返扫描轨迹。",
      "description_en": "Define forward and backward linear scan trajectories for a selected axis."
    },
    {
      "action_name": "auto-define_line_trajectories_general",
      "description": "按给定起止值和扫描参数定义通用线扫描轨迹。",
      "description_en": "Define a general line-scan trajectory using supplied start, stop, and scan parameters."
    },
    {
      "action_name": "auto-delete_script",
      "description": "删除控制器中的脚本文件。",
      "description_en": "Delete a script file stored in the controller."
    },
    {
      "action_name": "auto-disable_group",
      "description": "禁用指定轴组。",
      "description_en": "Disable the selected motion group."
    },
    {
      "action_name": "auto-disconnect",
      "description": "断开与运动控制器的连接。",
      "description_en": "Disconnect from the motion controller."
    },
    {
      "action_name": "auto-download_script",
      "description": "从控制器导出脚本文件。",
      "description_en": "Download a script file from the controller."
    },
    {
      "action_name": "auto-download_trajectory",
      "description": "从控制器导出轨迹文件。",
      "description_en": "Download a trajectory file from the controller."
    },
    {
      "action_name": "auto-enable_group",
      "description": "使能指定轴组。",
      "description_en": "Enable the selected motion group."
    },
    {
      "action_name": "auto-execute_script",
      "description": "执行控制器中的TCL脚本任务。",
      "description_en": "Execute a TCL script task on the controller."
    },
    {
      "action_name": "auto-home_allgroups",
      "description": "对所有轴组执行回零。",
      "description_en": "Home all motion groups."
    },
    {
      "action_name": "auto-home_group",
      "description": "对指定轴组执行回零。",
      "description_en": "Home the selected motion group."
    },
    {
      "action_name": "auto-initialize_allgroups",
      "description": "初始化所有轴组。",
      "description_en": "Initialize all motion groups."
    },
    {
      "action_name": "auto-initialize_group",
      "description": "初始化指定轴组，并可选择回零。",
      "description_en": "Initialize the selected motion group, optionally with homing."
    },
    {
      "action_name": "auto-kill_group",
      "description": "停止并复位指定轴组的运行状态。",
      "description_en": "Kill the selected motion group, stopping motion and resetting its running state."
    },
    {
      "action_name": "auto-list_scripts",
      "description": "列出控制器中已有的脚本文件。",
      "description_en": "List script files stored in the controller."
    },
    {
      "action_name": "auto-move_group",
      "description": "将指定轴组移动到目标位置。",
      "description_en": "Move the selected motion group to target positions."
    },
    {
      "action_name": "auto-move_stage",
      "description": "将指定轴移动到目标位置，或执行相对位移。",
      "description_en": "Move the selected stage to a target position, or by a relative offset."
    },
    {
      "action_name": "auto-move_to_trajectory_start",
      "description": "将轴组移动到指定轨迹的起始位置。",
      "description_en": "Move the motion group to the start position of a selected trajectory."
    },
    {
      "action_name": "auto-read_and_save",
      "description": "读取控制器采集到的运动数据并保存。",
      "description_en": "Read gathered motion data from the controller and save it."
    },
    {
      "action_name": "auto-read_gathering",
      "description": "读取控制器采集的运动数据缓冲区。",
      "description_en": "Read the controller's gathered motion data buffer."
    },
    {
      "action_name": "auto-read_script",
      "description": "读取控制器中脚本文件的内容。",
      "description_en": "Read the contents of a script file stored in the controller."
    },
    {
      "action_name": "auto-read_stage_position",
      "description": "获取轴位置。",
      "description_en": "get stage position"
    },
    {
      "action_name": "auto-read_systemini",
      "description": "读取控制器的系统配置并解析轴组信息。",
      "description_en": "Read the controller system configuration and populate group information."
    },
    {
      "action_name": "auto-reboot",
      "description": "重启运动控制器。",
      "description_en": "Reboot the motion controller."
    },
    {
      "action_name": "auto-run_line_trajectory_general",
      "description": "运行已定义的通用线扫描轨迹。",
      "description_en": "Run a previously defined general line-scan trajectory."
    },
    {
      "action_name": "auto-run_trajectory",
      "description": "以PVT模式运行已准备好的轨迹。",
      "description_en": "Run an armed trajectory in PVT mode."
    },
    {
      "action_name": "auto-save_gathering_file",
      "description": "将读取到的采集数据保存为文件。",
      "description_en": "Save the retrieved gathered data to a file."
    },
    {
      "action_name": "auto-save_stagesini",
      "description": "导出轴台配置文件 stages.ini。",
      "description_en": "Save the stage configuration file stages.ini from the controller."
    },
    {
      "action_name": "auto-save_systemini",
      "description": "导出系统配置文件 system.ini。",
      "description_en": "Save the system configuration file system.ini from the controller."
    },
    {
      "action_name": "auto-set_trajectory_group",
      "description": "设置后续轨迹操作所使用的轴组。",
      "description_en": "Set the motion group to be used for subsequent trajectory operations."
    },
    {
      "action_name": "auto-set_tuning",
      "description": "设置轴的闭环调谐参数。",
      "description_en": "set stage closed-loop tuning parameters"
    },
    {
      "action_name": "auto-set_velocity",
      "description": "设置轴的运动速度及相关加减速参数。",
      "description_en": "Set stage velocity and related acceleration or jerk parameters."
    },
    {
      "action_name": "auto-status_report",
      "description": "获取控制器与各轴组的状态报告。",
      "description_en": "Get a printable status report for the controller and its motion groups."
    },
    {
      "action_name": "auto-upload_script",
      "description": "向控制器上传脚本文件。",
      "description_en": "Upload a script file to the controller."
    },
    {
      "action_name": "auto-upload_stagesini",
      "description": "向控制器上传轴台配置文件 stages.ini。",
      "description_en": "Upload the stage configuration file stages.ini to the controller."
    },
    {
      "action_name": "auto-upload_systemini",
      "description": "向控制器上传系统配置文件 system.ini。",
      "description_en": "Upload the system configuration file system.ini to the controller."
    },
    {
      "action_name": "auto-upload_trajectory",
      "description": "向控制器上传轨迹文件。",
      "description_en": "Upload a trajectory file to the controller."
    },
    {
      "action_name": "auto-get_tuning",
      "description": "获取轴的闭环调谐参数。",
      "description_en": "get stage closed-loop tuning parameters"
    },
    {
      "action_name": "auto-get_group_status",
      "description": "获取各轴组状态。",
      "description_en": "get status of each motion group"
    },
    {
      "action_name": "auto-get_hardware_status",
      "description": "获取各轴硬件状态。",
      "description_en": "get hardware status of each stage"
    },
    {
      "action_name": "auto-get_positioner_errors",
      "description": "获取各轴定位器错误状态。",
      "description_en": "get positioner error status for each stage"
    },
    {
      "action_name": "auto-get_stage_position",
      "description": "获取轴位置。",
      "description_en": "get stage position"
    },
    {
      "action_name": "auto-get_trajectory",
      "description": "获取已定义轨迹的信息。",
      "description_en": "get information about a defined trajectory"
    }
  ]
}

